package com.yeyamo_mobile.api.gamification_service.domain;import static org.junit.jupiter.api.Assertions.*;import java.time.Instant;import java.util.UUID;import org.junit.jupiter.api.Test;
class ProgressDomainTest{@Test void computesDeterministicLevels(){assertEquals(1,Progress.levelFor(0));assertEquals(2,Progress.levelFor(100));assertEquals(3,Progress.levelFor(400));assertEquals(4,Progress.levelFor(900));}@Test void exposesNextLevelThreshold(){var p=new Progress("u",450,3,1,2,null,Instant.now());assertEquals(900,p.xpForNextLevel());}@Test void activityRequiresPositiveXp(){assertThrows(IllegalArgumentException.class,()->new XpActivity(UUID.randomUUID(),"u",0,"LIKE","p1","SOCIAL",null,Instant.now()));}}
